const fs = require('fs');
const util = require('util');

console.log("Attempting to read file...");

// 1. The classic Error-First Callback
// arg 1: error, arg 2: data
fs.readFile('does-not-exist.txt', 'utf-8', (error, data) => {
  // YOU MUST CHECK THE ERROR FIRST!
  if (error) {
    console.log("Callback Caught an Error! File missing.");
    return;
  }

  // If we reach here, we know it's safe to use the data
  console.log(data);
});

// 2. Modernizing it using util.promisify
const readFilePromise = util.promisify(fs.readFile);

async function readModern() {
  try {
    // Now we can use async/await!
    const data = await readFilePromise('does-not-exist.txt', 'utf-8');
  } catch (err) {
    console.log("Promisify Caught an Error too!");
  }
}
readModern();
